const SCHEMA = `
  CREATE TABLE IF NOT EXISTS tags (
    id INTEGER PRIMARY KEY AUTOINCREMENT,
    name TEXT NOT NULL UNIQUE,
    color TEXT NOT NULL DEFAULT '#6366f1',
    isProductive INTEGER NOT NULL DEFAULT 1
  );

  CREATE TABLE IF NOT EXISTS tasks (
    id INTEGER PRIMARY KEY AUTOINCREMENT,
    title TEXT NOT NULL,
    tagId INTEGER REFERENCES tags(id) ON DELETE SET NULL,
    secondaryTagId INTEGER REFERENCES tags(id) ON DELETE SET NULL,
    startTime TEXT NOT NULL,
    endTime TEXT,
    studyNodeId INTEGER
  );

  INSERT OR IGNORE INTO tags (id, name, color, isProductive)
  VALUES (1, 'Idle', '#6b7280', 0);

  INSERT OR IGNORE INTO tags (id, name, color, isProductive)
  VALUES (2, 'Work', '#3b82f6', 1);

  INSERT OR IGNORE INTO tags (id, name, color, isProductive)
  VALUES (3, 'Break', '#f59e0b', 0);
  CREATE TABLE IF NOT EXISTS day_configs (
    date TEXT PRIMARY KEY,
    isWorkDay INTEGER NOT NULL DEFAULT 0
  );

  -- ── RickOS: Organização ──────────────────────────────────────────────
  CREATE TABLE IF NOT EXISTS projects (
    id INTEGER PRIMARY KEY AUTOINCREMENT,
    name TEXT NOT NULL,
    description TEXT,
    githubRepoUrl TEXT,
    color TEXT NOT NULL DEFAULT '#6366f1',
    archived INTEGER NOT NULL DEFAULT 0,
    claudeCommand TEXT,
    localPath TEXT,
    stage TEXT NOT NULL DEFAULT 'ideia',   -- ideia|validacao|mvp|lancado|monetizando|morto|trabalho
    businessModel TEXT,
    pricing TEXT,
    audience TEXT
  );

  CREATE TABLE IF NOT EXISTS project_milestones (
    id INTEGER PRIMARY KEY AUTOINCREMENT,
    projectId INTEGER NOT NULL REFERENCES projects(id) ON DELETE CASCADE,
    title TEXT NOT NULL,
    targetDate TEXT,
    doneAt TEXT,
    createdAt TEXT NOT NULL
  );

  -- Central de Projetos: ciclos/versões, histórico de decisões e base de conhecimento
  CREATE TABLE IF NOT EXISTS project_cycles (
    id INTEGER PRIMARY KEY AUTOINCREMENT,
    projectId INTEGER NOT NULL REFERENCES projects(id) ON DELETE CASCADE,
    name TEXT NOT NULL,                     -- ex: v1.3, Ciclo de novembro
    goal TEXT,                              -- o que este ciclo entrega
    startDate TEXT NOT NULL,                -- YYYY-MM-DD
    dueDate TEXT,                           -- prazo atual (YYYY-MM-DD)
    originalDueDate TEXT,                   -- prazo antes das extensões
    extensions INTEGER NOT NULL DEFAULT 0,
    status TEXT NOT NULL DEFAULT 'ativo',   -- ativo | concluido | cancelado
    closedAt TEXT,
    retrospective TEXT,
    createdAt TEXT NOT NULL
  );

  CREATE TABLE IF NOT EXISTS project_events (
    id INTEGER PRIMARY KEY AUTOINCREMENT,
    projectId INTEGER NOT NULL REFERENCES projects(id) ON DELETE CASCADE,
    kind TEXT NOT NULL,                     -- status | decisao | proxima_acao | onde_parei | bloqueio | ciclo | marco | revisao | nota
    fromStatus TEXT,
    toStatus TEXT,
    text TEXT,
    createdAt TEXT NOT NULL
  );
  CREATE INDEX IF NOT EXISTS idx_project_events_project ON project_events(projectId, createdAt);

  CREATE TABLE IF NOT EXISTS project_notes (
    id INTEGER PRIMARY KEY AUTOINCREMENT,
    projectId INTEGER NOT NULL REFERENCES projects(id) ON DELETE CASCADE,
    kind TEXT NOT NULL DEFAULT 'nota',      -- nota | link | decisao
    title TEXT NOT NULL,
    body TEXT,
    url TEXT,
    pinned INTEGER NOT NULL DEFAULT 0,
    createdAt TEXT NOT NULL
  );

  -- Próximas ações delegadas ao Claude (rodam num worktree isolado, voltam para revisão)
  CREATE TABLE IF NOT EXISTS project_delegations (
    id INTEGER PRIMARY KEY AUTOINCREMENT,
    projectId INTEGER NOT NULL REFERENCES projects(id) ON DELETE CASCADE,
    action TEXT NOT NULL,
    instructions TEXT,
    repoPath TEXT NOT NULL,
    branch TEXT NOT NULL,
    worktreePath TEXT NOT NULL,
    baseRef TEXT,
    status TEXT NOT NULL DEFAULT 'rodando', -- rodando | pronta | erro | cancelada | aceita | descartada
    output TEXT,
    error TEXT,
    prUrl TEXT,
    createdAt TEXT NOT NULL,
    finishedAt TEXT
  );

  CREATE TABLE IF NOT EXISTS todos (
    id INTEGER PRIMARY KEY AUTOINCREMENT,
    title TEXT NOT NULL,
    notes TEXT,
    status TEXT NOT NULL DEFAULT 'inbox',   -- inbox | todo | doing | done
    priority INTEGER NOT NULL DEFAULT 0,
    dueDate TEXT,
    projectId INTEGER REFERENCES projects(id) ON DELETE SET NULL,
    source TEXT NOT NULL DEFAULT 'manual',  -- manual | quick-capture | github
    aiGenerated INTEGER NOT NULL DEFAULT 0,
    recurrence TEXT,                        -- JSON: { type, n?, day? } | null
    type TEXT NOT NULL DEFAULT 'projeto',   -- projeto | compra | urgente | lembrete
    createdAt TEXT NOT NULL
  );

  CREATE TABLE IF NOT EXISTS habits (
    id INTEGER PRIMARY KEY AUTOINCREMENT,
    name TEXT NOT NULL,
    frequency TEXT NOT NULL DEFAULT 'daily',
    target INTEGER NOT NULL DEFAULT 1,
    active INTEGER NOT NULL DEFAULT 1
  );

  CREATE TABLE IF NOT EXISTS habit_entries (
    habitId INTEGER NOT NULL REFERENCES habits(id) ON DELETE CASCADE,
    date TEXT NOT NULL,
    completed INTEGER NOT NULL DEFAULT 0,
    completedAt TEXT,
    PRIMARY KEY (habitId, date)
  );

  -- ── RickOS: Finanças ─────────────────────────────────────────────────
  CREATE TABLE IF NOT EXISTS accounts (
    id INTEGER PRIMARY KEY AUTOINCREMENT,
    name TEXT NOT NULL,
    currency TEXT NOT NULL DEFAULT 'BRL',
    balance REAL NOT NULL DEFAULT 0
  );

  CREATE TABLE IF NOT EXISTS categories (
    id INTEGER PRIMARY KEY AUTOINCREMENT,
    name TEXT NOT NULL,
    type TEXT NOT NULL DEFAULT 'expense',   -- income | expense
    color TEXT NOT NULL DEFAULT '#6366f1'
  );

  CREATE TABLE IF NOT EXISTS transactions (
    id INTEGER PRIMARY KEY AUTOINCREMENT,
    accountId INTEGER REFERENCES accounts(id) ON DELETE SET NULL,
    categoryId INTEGER REFERENCES categories(id) ON DELETE SET NULL,
    amount REAL NOT NULL,
    currency TEXT NOT NULL DEFAULT 'BRL',
    type TEXT NOT NULL DEFAULT 'expense',   -- income | expense
    description TEXT,
    date TEXT NOT NULL
  );

  CREATE TABLE IF NOT EXISTS budgets (
    id INTEGER PRIMARY KEY AUTOINCREMENT,
    categoryId INTEGER REFERENCES categories(id) ON DELETE CASCADE,
    month TEXT NOT NULL,
    amount REAL NOT NULL
  );

  CREATE TABLE IF NOT EXISTS investments (
    id INTEGER PRIMARY KEY AUTOINCREMENT,
    name TEXT NOT NULL,
    type TEXT,
    amount REAL NOT NULL DEFAULT 0,
    currency TEXT NOT NULL DEFAULT 'BRL'
  );

  -- Monthly value snapshot per investment (YYYY-MM). One row per (investmentId, month).
  CREATE TABLE IF NOT EXISTS investment_history (
    id INTEGER PRIMARY KEY AUTOINCREMENT,
    investmentId INTEGER NOT NULL REFERENCES investments(id) ON DELETE CASCADE,
    month TEXT NOT NULL,
    amount REAL NOT NULL DEFAULT 0
  );

  INSERT OR IGNORE INTO categories (id, name, type, color) VALUES (1, 'Salário', 'income', '#22c55e');
  INSERT OR IGNORE INTO categories (id, name, type, color) VALUES (2, 'Alimentação', 'expense', '#f59e0b');
  INSERT OR IGNORE INTO categories (id, name, type, color) VALUES (3, 'Transporte', 'expense', '#3b82f6');
  INSERT OR IGNORE INTO categories (id, name, type, color) VALUES (4, 'Moradia', 'expense', '#8b5cf6');
  INSERT OR IGNORE INTO categories (id, name, type, color) VALUES (5, 'Lazer', 'expense', '#ec4899');
  INSERT OR IGNORE INTO categories (id, name, type, color) VALUES (6, 'Outros', 'expense', '#6b7280');

  -- ── RickOS: Viagens ──────────────────────────────────────────────────
  CREATE TABLE IF NOT EXISTS trips (
    id INTEGER PRIMARY KEY AUTOINCREMENT,
    origin TEXT,
    destination TEXT NOT NULL,
    startDate TEXT,
    endDate TEXT,
    budget REAL,
    currency TEXT NOT NULL DEFAULT 'BRL',
    status TEXT NOT NULL DEFAULT 'planned'
  );

  CREATE TABLE IF NOT EXISTS flight_watches (
    id INTEGER PRIMARY KEY AUTOINCREMENT,
    tripId INTEGER REFERENCES trips(id) ON DELETE CASCADE,
    origin TEXT,
    destination TEXT,
    price REAL,
    currency TEXT NOT NULL DEFAULT 'BRL',
    lastChecked TEXT
  );

  -- ── Monitoramento de passagens (server/flights/) ──
  -- Dinheiro em centavos (INTEGER) + moeda; config do monitor = JSON validado em código.
  CREATE TABLE IF NOT EXISTS flight_monitors (
    id INTEGER PRIMARY KEY AUTOINCREMENT,
    name TEXT NOT NULL,
    status TEXT NOT NULL DEFAULT 'active',
    tripId INTEGER REFERENCES trips(id) ON DELETE SET NULL,
    config TEXT NOT NULL,
    createdAt TEXT NOT NULL,
    updatedAt TEXT NOT NULL,
    lastRunAt TEXT,
    lastSuccessAt TEXT,
    nextRunAt TEXT,
    lastError TEXT,
    extraDisplay INTEGER NOT NULL DEFAULT 0,
    legacyWatchId INTEGER UNIQUE,
    legacy TEXT
  );

  CREATE TABLE IF NOT EXISTS flight_runs (
    id INTEGER PRIMARY KEY AUTOINCREMENT,
    monitorId INTEGER NOT NULL REFERENCES flight_monitors(id) ON DELETE CASCADE,
    trigger TEXT NOT NULL,
    status TEXT NOT NULL,
    startedAt TEXT NOT NULL,
    finishedAt TEXT,
    planned INTEGER NOT NULL DEFAULT 0,
    done INTEGER NOT NULL DEFAULT 0,
    failed INTEGER NOT NULL DEFAULT 0,
    queries INTEGER NOT NULL DEFAULT 0,
    cacheHits INTEGER NOT NULL DEFAULT 0,
    offersFound INTEGER NOT NULL DEFAULT 0,
    aiCalls INTEGER NOT NULL DEFAULT 0,
    tokens INTEGER NOT NULL DEFAULT 0,
    message TEXT
  );

  -- Plano/cobertura: uma linha por consulta atômica; UNIQUE(monitorId, key) = idempotência.
  CREATE TABLE IF NOT EXISTS flight_search_tasks (
    id INTEGER PRIMARY KEY AUTOINCREMENT,
    monitorId INTEGER NOT NULL REFERENCES flight_monitors(id) ON DELETE CASCADE,
    key TEXT NOT NULL,
    provider TEXT NOT NULL,
    stage TEXT NOT NULL,
    origin TEXT NOT NULL,
    destination TEXT NOT NULL,
    departDate TEXT NOT NULL,
    returnDate TEXT,
    priority REAL NOT NULL DEFAULT 0,
    status TEXT NOT NULL DEFAULT 'pending',
    attempts INTEGER NOT NULL DEFAULT 0,
    nextAttemptAt TEXT,
    lastError TEXT,
    resultCount INTEGER NOT NULL DEFAULT 0,
    minPriceMinor INTEGER,
    currency TEXT,
    runId INTEGER,
    createdAt TEXT NOT NULL,
    finishedAt TEXT,
    UNIQUE (monitorId, key)
  );
  CREATE INDEX IF NOT EXISTS idx_flight_tasks_status ON flight_search_tasks (monitorId, status, priority);

  -- Ofertas deduplicadas por itinerário (fingerprint independe de provedor e preço).
  CREATE TABLE IF NOT EXISTS flight_offers (
    id INTEGER PRIMARY KEY AUTOINCREMENT,
    monitorId INTEGER NOT NULL REFERENCES flight_monitors(id) ON DELETE CASCADE,
    fingerprint TEXT NOT NULL,
    provider TEXT NOT NULL,
    origin TEXT NOT NULL,
    destination TEXT NOT NULL,
    departDate TEXT NOT NULL,
    returnDate TEXT,
    priceMinor INTEGER NOT NULL,
    currency TEXT NOT NULL,
    prevPriceMinor INTEGER,
    prevCurrency TEXT,
    verification TEXT NOT NULL,
    data TEXT NOT NULL,
    sources TEXT NOT NULL DEFAULT '[]',
    firstSeenAt TEXT NOT NULL,
    lastSeenAt TEXT NOT NULL,
    available INTEGER NOT NULL DEFAULT 1,
    favorite INTEGER NOT NULL DEFAULT 0,
    UNIQUE (monitorId, fingerprint)
  );
  CREATE INDEX IF NOT EXISTS idx_flight_offers_monitor ON flight_offers (monitorId, available);

  -- Histórico: toda observação de preço (sobrevive à oferta sumir).
  CREATE TABLE IF NOT EXISTS flight_price_observations (
    id INTEGER PRIMARY KEY AUTOINCREMENT,
    offerId INTEGER NOT NULL REFERENCES flight_offers(id) ON DELETE CASCADE,
    monitorId INTEGER NOT NULL,
    observedAt TEXT NOT NULL,
    priceMinor INTEGER NOT NULL,
    currency TEXT NOT NULL,
    provider TEXT NOT NULL,
    verification TEXT NOT NULL,
    paxKey TEXT NOT NULL,
    runId INTEGER,
    UNIQUE (offerId, provider, observedAt)
  );
  CREATE INDEX IF NOT EXISTS idx_flight_obs_monitor ON flight_price_observations (monitorId, observedAt);

  -- Alertas já disparados (dedupeKey UNIQUE = sem notificação duplicada).
  CREATE TABLE IF NOT EXISTS flight_alert_events (
    id INTEGER PRIMARY KEY AUTOINCREMENT,
    monitorId INTEGER NOT NULL REFERENCES flight_monitors(id) ON DELETE CASCADE,
    offerId INTEGER,
    kind TEXT NOT NULL,
    dedupeKey TEXT NOT NULL UNIQUE,
    message TEXT NOT NULL,
    createdAt TEXT NOT NULL
  );

  -- Combinações rota × datas que o usuário acompanha (entram ao pesquisar no Skyscanner).
  CREATE TABLE IF NOT EXISTS flight_tracked_combos (
    id INTEGER PRIMARY KEY AUTOINCREMENT,
    monitorId INTEGER NOT NULL REFERENCES flight_monitors(id) ON DELETE CASCADE,
    origin TEXT NOT NULL,
    destination TEXT NOT NULL,
    departDate TEXT NOT NULL,
    returnDate TEXT NOT NULL DEFAULT '',
    createdAt TEXT NOT NULL,
    UNIQUE (monitorId, origin, destination, departDate, returnDate)
  );

  -- Cache de respostas de provedores e de rotas terrestres (compartilhado entre monitores).
  CREATE TABLE IF NOT EXISTS flight_cache (
    key TEXT PRIMARY KEY,
    value TEXT NOT NULL,
    expiresAt TEXT NOT NULL
  );

  -- Consultas por provedor por dia (cota diária).
  CREATE TABLE IF NOT EXISTS flight_provider_usage (
    provider TEXT NOT NULL,
    day TEXT NOT NULL,
    queries INTEGER NOT NULL DEFAULT 0,
    PRIMARY KEY (provider, day)
  );

  CREATE TABLE IF NOT EXISTS trip_documents (
    tripId INTEGER NOT NULL REFERENCES trips(id) ON DELETE CASCADE,
    item TEXT NOT NULL,
    checked INTEGER NOT NULL DEFAULT 0,
    PRIMARY KEY (tripId, item)
  );

  -- ── RickOS: Settings & integrações ───────────────────────────────────
  CREATE TABLE IF NOT EXISTS settings (
    key TEXT PRIMARY KEY,
    value TEXT
  );

  CREATE TABLE IF NOT EXISTS github_issues (
    id INTEGER PRIMARY KEY,          -- GitHub's global issue id (negative for local-only)
    number INTEGER NOT NULL,
    title TEXT NOT NULL,
    state TEXT NOT NULL,             -- open | closed
    repo TEXT NOT NULL,              -- owner/name
    url TEXT,                        -- NULL until it exists on GitHub
    labels TEXT,                     -- JSON array of label names
    milestone TEXT,
    updatedAt TEXT,
    local INTEGER NOT NULL DEFAULT 0, -- 1 = created in-app, survives sync
    body TEXT                         -- description (used when creating on GitHub)
  );

  CREATE TABLE IF NOT EXISTS calendar_events (
    id INTEGER PRIMARY KEY AUTOINCREMENT,
    title TEXT NOT NULL,
    startTime TEXT NOT NULL,         -- ISO
    endTime TEXT,
    location TEXT,
    source TEXT NOT NULL DEFAULT 'manual'  -- manual | google
  );

  -- ── RickOS: IA (skills, agentes, execuções) ──────────────────────────
  CREATE TABLE IF NOT EXISTS skills (
    id TEXT PRIMARY KEY,
    name TEXT NOT NULL,
    description TEXT,
    category TEXT,
    tags TEXT NOT NULL DEFAULT '[]',
    content TEXT NOT NULL DEFAULT '',
    isFavorite INTEGER NOT NULL DEFAULT 0,
    usageCount INTEGER NOT NULL DEFAULT 0,
    createdAt TEXT NOT NULL,
    updatedAt TEXT NOT NULL
  );

  CREATE TABLE IF NOT EXISTS agents (
    id TEXT PRIMARY KEY,
    name TEXT NOT NULL,
    description TEXT,
    role TEXT,
    systemPrompt TEXT NOT NULL DEFAULT '',
    defaultSkillIds TEXT NOT NULL DEFAULT '[]',
    tags TEXT NOT NULL DEFAULT '[]',
    isFavorite INTEGER NOT NULL DEFAULT 0,
    createdAt TEXT NOT NULL,
    updatedAt TEXT NOT NULL
  );

  CREATE TABLE IF NOT EXISTS prompt_executions (
    id TEXT PRIMARY KEY,
    createdAt TEXT NOT NULL,
    agentId TEXT,
    skillIds TEXT NOT NULL DEFAULT '[]',
    userPrompt TEXT NOT NULL DEFAULT '',
    finalPrompt TEXT NOT NULL DEFAULT '',
    response TEXT
  );

  CREATE TABLE IF NOT EXISTS links (
    id INTEGER PRIMARY KEY AUTOINCREMENT,
    title TEXT NOT NULL,
    url TEXT NOT NULL,
    checked INTEGER NOT NULL DEFAULT 0,
    tags TEXT NOT NULL DEFAULT '[]',
    lastOpenedAt TEXT,
    createdAt TEXT NOT NULL
  );

  -- ── Estudos (Learning OS) ──
  CREATE TABLE IF NOT EXISTS study_topics (
    id INTEGER PRIMARY KEY AUTOINCREMENT,
    name TEXT NOT NULL,
    category TEXT,
    status TEXT NOT NULL DEFAULT 'studying',  -- studying | planned | paused | completed
    targetDate TEXT,
    priority INTEGER NOT NULL DEFAULT 0,
    color TEXT NOT NULL DEFAULT '#6366f1',
    createdAt TEXT NOT NULL
  );

  CREATE TABLE IF NOT EXISTS study_nodes (
    id INTEGER PRIMARY KEY AUTOINCREMENT,
    topicId INTEGER NOT NULL REFERENCES study_topics(id) ON DELETE CASCADE,
    parentId INTEGER,                        -- self-ref; null = raiz
    title TEXT NOT NULL,
    description TEXT,
    status TEXT NOT NULL DEFAULT 'todo',     -- todo | doing | done
    orderIndex INTEGER NOT NULL DEFAULT 0,
    estimatedHours REAL,
    completedAt TEXT,
    createdAt TEXT NOT NULL
  );

  CREATE TABLE IF NOT EXISTS study_notes (
    id INTEGER PRIMARY KEY AUTOINCREMENT,
    topicId INTEGER NOT NULL REFERENCES study_topics(id) ON DELETE CASCADE,
    nodeId INTEGER REFERENCES study_nodes(id) ON DELETE CASCADE,  -- null = nota do tópico
    content TEXT NOT NULL DEFAULT '',
    updatedAt TEXT NOT NULL
  );

  CREATE TABLE IF NOT EXISTS study_flashcards (
    id INTEGER PRIMARY KEY AUTOINCREMENT,
    topicId INTEGER NOT NULL REFERENCES study_topics(id) ON DELETE CASCADE,
    nodeId INTEGER REFERENCES study_nodes(id) ON DELETE SET NULL,
    front TEXT NOT NULL,
    back TEXT NOT NULL,
    easeFactor REAL NOT NULL DEFAULT 2.5,
    intervalDays INTEGER NOT NULL DEFAULT 0,
    repetitions INTEGER NOT NULL DEFAULT 0,
    nextReviewAt TEXT,
    lastReviewedAt TEXT,
    createdAt TEXT NOT NULL
  );

  -- Log append-only de revisões de flashcards (1 linha por revisão) → heatmap
  CREATE TABLE IF NOT EXISTS study_review_log (
    id INTEGER PRIMARY KEY AUTOINCREMENT,
    flashcardId INTEGER NOT NULL REFERENCES study_flashcards(id) ON DELETE CASCADE,
    topicId INTEGER NOT NULL,
    rating TEXT,                             -- again | hard | good | easy
    reviewedAt TEXT NOT NULL                 -- ISO timestamp
  );

  CREATE TABLE IF NOT EXISTS study_quiz_attempts (
    id INTEGER PRIMARY KEY AUTOINCREMENT,
    topicId INTEGER NOT NULL REFERENCES study_topics(id) ON DELETE CASCADE,
    score INTEGER NOT NULL DEFAULT 0,
    total INTEGER NOT NULL DEFAULT 0,
    durationMs INTEGER,
    createdAt TEXT NOT NULL
  );

  -- Travel Stay Finder (busca de hospedagens)
  CREATE TABLE IF NOT EXISTS travel_stay_favorites (
    id TEXT PRIMARY KEY,
    tripId INTEGER,
    provider TEXT,
    listingUrl TEXT,
    title TEXT,
    pricePerNight REAL,
    currency TEXT,
    data TEXT NOT NULL DEFAULT '{}',
    createdAt TEXT NOT NULL
  );
  CREATE TABLE IF NOT EXISTS travel_stay_watches (
    id TEXT PRIMARY KEY,
    city TEXT NOT NULL,
    filters TEXT NOT NULL DEFAULT '{}',
    currentPrice REAL NOT NULL DEFAULT 0,
    bestPrice REAL NOT NULL DEFAULT 0,
    currency TEXT NOT NULL DEFAULT 'BRL',
    lastCheckedAt TEXT,
    createdAt TEXT NOT NULL
  );
  CREATE TABLE IF NOT EXISTS travel_stay_price_history (
    id TEXT PRIMARY KEY,
    watchId TEXT NOT NULL,
    checkedAt TEXT NOT NULL,
    price REAL NOT NULL,
    currency TEXT NOT NULL DEFAULT 'BRL'
  );
  CREATE TABLE IF NOT EXISTS travel_stay_search_history (
    id INTEGER PRIMARY KEY AUTOINCREMENT,
    filters TEXT NOT NULL,
    createdAt TEXT NOT NULL
  );

  -- CRM pessoal (manutenção de relações importantes)
  CREATE TABLE IF NOT EXISTS contacts (
    id INTEGER PRIMARY KEY AUTOINCREMENT,
    name TEXT NOT NULL,
    location TEXT,             -- cidade/país (texto livre, legado)
    country TEXT,              -- país (dropdown)
    state TEXT,                -- estado/UF (dropdown quando país = Brasil)
    birthday TEXT,             -- MM-DD ou YYYY-MM-DD
    interests TEXT,
    context TEXT,              -- o que está acontecendo na vida dela
    lastContactAt TEXT,        -- ISO da última conversa
    nextFollowUp TEXT,         -- YYYY-MM-DD
    createdAt TEXT NOT NULL
  );

  -- Automações: motor de regras (condição → ação)
  CREATE TABLE IF NOT EXISTS rules (
    id INTEGER PRIMARY KEY AUTOINCREMENT,
    type TEXT NOT NULL,            -- idle_productive | budget_threshold | due_flashcards
    enabled INTEGER NOT NULL DEFAULT 1,
    params TEXT NOT NULL DEFAULT '{}',
    lastFiredAt TEXT,
    createdAt TEXT NOT NULL
  );

  -- Automações: agendador de agentes → Inbox
  CREATE TABLE IF NOT EXISTS scheduled_jobs (
    id INTEGER PRIMARY KEY AUTOINCREMENT,
    name TEXT NOT NULL,
    prompt TEXT NOT NULL,
    hour INTEGER NOT NULL DEFAULT 7,
    enabled INTEGER NOT NULL DEFAULT 1,
    lastRunAt TEXT,
    createdAt TEXT NOT NULL
  );

  -- Metas mensais (opcionalmente ligadas a um projeto ou tópico de estudo)
  CREATE TABLE IF NOT EXISTS goals (
    id INTEGER PRIMARY KEY AUTOINCREMENT,
    month TEXT NOT NULL,            -- YYYY-MM
    title TEXT NOT NULL,
    kind TEXT NOT NULL DEFAULT 'free',  -- free | project | study
    refId INTEGER,                 -- projectId ou study_topicId conforme kind
    target REAL NOT NULL DEFAULT 1,
    current REAL NOT NULL DEFAULT 0,
    unit TEXT,
    done INTEGER NOT NULL DEFAULT 0,
    createdAt TEXT NOT NULL
  );

  -- Uso de tokens das execuções do Claude CLI (por módulo/projeto)
  CREATE TABLE IF NOT EXISTS ai_usage (
    id INTEGER PRIMARY KEY AUTOINCREMENT,
    createdAt TEXT NOT NULL,
    source TEXT NOT NULL,          -- módulo de origem (assistente, estudos, agendador…)
    projectId INTEGER,
    model TEXT,
    inputTokens INTEGER NOT NULL DEFAULT 0,
    outputTokens INTEGER NOT NULL DEFAULT 0,
    cacheReadTokens INTEGER NOT NULL DEFAULT 0,
    cacheCreationTokens INTEGER NOT NULL DEFAULT 0,
    costUsd REAL NOT NULL DEFAULT 0,
    durationMs INTEGER,
    numTurns INTEGER,
    isError INTEGER NOT NULL DEFAULT 0
  );
  CREATE INDEX IF NOT EXISTS idx_ai_usage_createdAt ON ai_usage(createdAt);

  -- Central de notificações (sino da sidebar): regras, agentes, IA, sistema
  CREATE TABLE IF NOT EXISTS notifications (
    id INTEGER PRIMARY KEY AUTOINCREMENT,
    createdAt TEXT NOT NULL,
    title TEXT NOT NULL,
    body TEXT NOT NULL DEFAULT '',
    source TEXT NOT NULL DEFAULT 'sistema', -- automacao | agendador | ia | sistema | …
    page TEXT,                              -- página do app aberta ao clicar (opcional)
    readAt TEXT
  );
  CREATE INDEX IF NOT EXISTS idx_notifications_createdAt ON notifications(createdAt);
`;
